<script setup>
import {ref,computed} from 'vue';import {can,fieldAccess,money,cents,approvalStage,approvalStageLabel,approvalRequirement} from './domain.js';import {suiteRows,suiteStatus,canSuiteAct,comparisons,contractTypes,formForKind,suiteFields} from './vendor-suite.js';import {vendorReports} from './dashboard.js';import MetaFields from './MetaFields.vue';
const props=defineProps(['state','user','tenantId','page','execute','busy','failure']);const emit=defineEmits(['raise-order']);
const selected=ref(''),query=ref(''),dialog=ref(''),form=ref({}),formRef=ref(null),error=ref('');const today=()=>new Date().toISOString().slice(0,10);
const rows=k=>suiteRows(props.state,k,props.tenantId);const allowed=(a,f)=>can(props.state,props.user,props.tenantId,a,f);const mode=(k,f)=>fieldAccess(props.state,props.user,props.tenantId,k,f);const editable=k=>allowed('create',formForKind(k))&&suiteFields[k].every(x=>mode(x,formForKind(k))==='edit');
const packages=computed(()=>rows('rfq').filter(r=>(r.title+' '+r.description).toLowerCase().includes(query.value.toLowerCase())));const active=computed(()=>packages.value.find(r=>r.id===selected.value)||packages.value[0]);const bids=computed(()=>active.value?comparisons(props.state,active.value):[]);const decisions=computed(()=>rows('award').filter(a=>a.rfqId===active.value?.id));const decision=computed(()=>decisions.value.find(a=>suiteStatus(props.state,a)!=='Rejected'));const vendors=computed(()=>props.state.vendors.filter(v=>v.tenantId===props.tenantId&&!v.deleted&&(!v.onboardingStatus||v.onboardingStatus==='Active')));const report=computed(()=>(props.state.vendorReports||vendorReports(props.state,props.user)).filter(r=>r.tenantId===props.tenantId));
const who=id=>props.state.users.find(u=>u.id===id)?.name||'Project user';const quote=id=>rows('quotation').find(q=>q.id===id);const req=v=>!!String(v??'').trim()||'Required';const pos=v=>Number(v)>0||'Use a positive value';
const label=a=>approvalStageLabel(approvalStage(props.state,props.user,props.tenantId,a,props.state.suiteEvents.map(e=>({...e,amendmentId:e.documentId})),'quotation_selection'));
function open(k,d){error.value='';dialog.value=k;if(d&&k!=='award'){form.value=JSON.parse(JSON.stringify(d));if(k==='quotation')form.value.price=String(d.amount/100);return;}if(k==='rfq')form.value={title:'',description:'',contractType:'Material construction',referenceOrderId:'',data:{}};if(k==='quotation')form.value={rfqId:active.value?.id,vendorId:'',number:'',quotationDate:today(),description:active.value?.description||'',price:'',deliveryDays:30,creditDays:30,terms:'',data:{}};if(k==='award')form.value={quotationId:d.id,reason:'',data:{}};if(k==='vendor_feedback')form.value={vendorId:'',orderId:'',quality:3,timeliness:3,safety:3,communication:3,date:today(),comments:'',data:{}};}
async function save(){try{error.value='';if(formRef.value&&!(await formRef.value.validate()).valid)return;const d={...form.value,recordKind:dialog.value};if(dialog.value==='quotation'){d.amount=cents(d.price);for(const k of ['deliveryDays','creditDays'])d[k]=Number(d[k]);}if(dialog.value==='vendor_feedback')for(const k of ['quality','timeliness','safety','communication'])d[k]=Number(d[k]);const r=await props.execute('suite-save',d,'Record saved',false);if(r)dialog.value='';}catch(e){error.value=e.message;}}
async function action(d,a){await props.execute('suite-transition',{id:d.id,action:a},'Quotation selection '+a,false);}
function exportReport(){const keys=['name','status','quotations','selected','orders','workOrderValue','purchaseValue','paid','tds','outstanding','rating'].filter(k=>report.value.some(r=>r[k]!=null));const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"';const csv=[keys.join(','),...report.value.map(r=>keys.map(k=>cell(k.endsWith('Value')||['paid','tds','outstanding'].includes(k)?r[k]==null?'':r[k]/100:r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='VRISE-vendor-report.csv';a.click();URL.revokeObjectURL(url);}
</script>
<template>
<template v-if="page==='quotations'"><div class="workflow-banner"><v-icon color="primary">mdi-file-compare</v-icon><div><strong>Compare quotations before issuing a work order</strong><p>Compare value, execution time, credit days and terms. The reviewer chooses the quotation; selection rationale and approvals are retained.</p></div></div><section class="panel mb-6"><div class="panel-top"><div><h2>Quotation work packages</h2><p>Use a new scope or reference an existing project work order.</p></div><v-btn v-if="editable('rfq')" color="primary" prepend-icon="mdi-plus" @click="open('rfq')">New work package</v-btn></div><div class="table-toolbar"><v-select v-model="selected" :model-value="active?.id" :items="packages.map(r=>({title:r.title,value:r.id}))" label="Compare work package" hide-details/><v-btn v-if="active&&editable('quotation')&&!decision" color="primary" variant="outlined" @click="open('quotation')">Add quotation</v-btn></div><div v-if="active" class="detail-content"><h3>{{active.title}}</h3><p>{{active.description}}</p><span class="role-pill">{{active.contractType}}</span><p class="small muted mt-3">{{active.referenceOrderId?'Reference: '+(state.orders.find(o=>o.id===active.referenceOrderId)?.number||'Restricted'):'New work scope'}}</p><MetaFields :state="state" :user="user" :tenant-id="tenantId" form-id="quotation_request" :record="active" readonly/><v-btn v-if="editable('rfq')&&!bids.length" variant="text" @click="open('rfq',active)">Edit package</v-btn></div><div v-else class="empty-state">Create a work package to collect vendor quotations.</div></section><section v-if="active" class="panel"><div class="panel-top"><h2>Quotation comparison</h2><span class="quiet-label">Manual selection · all quotations shown</span></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>VENDOR / QUOTATION</th><th>VALUE INCLUDING TAX</th><th>DELIVERY</th><th>CREDIT DAYS</th><th>WORK ORDER PATH</th><th>TERMS</th><th></th></tr></thead><tbody><tr v-for="q in bids" :key="q.id"><td><strong>{{q.vendor||'Restricted'}}</strong><span class="cell-secondary">{{q.number}} · {{q.quotationDate||'—'}}</span></td><td>{{money(q.amount)}}</td><td>{{q.deliveryDays??'Restricted'}} days</td><td>{{q.creditDays??'—'}} days</td><td>{{state.orders.find(o=>o.quotationId===q.id)?.number || (decision?.quotationId===q.id?suiteStatus(state,decision):'Available for manual selection')}}</td><td class="scope-cell">{{q.terms||'Restricted'}}<div v-for="(v,k) in q.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td><td><v-btn v-if="editable('award')&&!decision" variant="outlined" size="small" @click="open('award',q)">Select for work order</v-btn><v-btn v-if="editable('quotation')&&!decision&&(user.superuser||q.createdBy===user.id)" variant="text" size="small" @click="open('quotation',q)">Edit</v-btn><v-btn v-if="decision?.quotationId===q.id&&suiteStatus(state,decision)==='Approved'&&!state.orders.some(o=>o.quotationId===q.id)&&allowed('create','work_order')" color="primary" size="small" @click="emit('raise-order',q)">Raise work order</v-btn></td></tr><tr v-if="!bids.length"><td colspan="7" class="empty-state">Add vendor quotations for this work package.</td></tr></tbody></table></div></section><section v-for="a in decisions" :key="a.id" class="panel mt-6"><div class="panel-top"><h2>Selection · {{quote(a.quotationId)?.number||'Restricted'}}</h2><span class="status-badge amber">{{suiteStatus(state,a)}}</span></div><div class="detail-content"><p>{{a.reason||'Rationale restricted'}}</p><p class="small muted mt-3">{{approvalRequirement(a)}}</p><MetaFields :state="state" :user="user" :tenant-id="tenantId" form-id="quotation_selection" :record="a" readonly/><div class="approval-actions"><v-btn v-for="act in ['submit','review','approve','reject'].filter(x=>canSuiteAct(state,user,tenantId,a,x))" :key="act" :loading="busy" :color="act==='reject'?'error':'primary'" @click="action(a,act)">{{act==='approve'?label(a):act==='review'?'Complete review':act==='submit'?'Submit':'Reject'}}</v-btn></div><div v-for="e in state.suiteEvents.filter(e=>e.documentId===a.id)" :key="e.id" class="event-line">{{e.action}} {{e.stage}} · {{who(e.actorId)}} · {{new Date(e.at).toLocaleString('en-IN')}}</div></div></section></template>
<template v-else-if="page==='feedback'"><section class="panel"><div class="panel-top"><div><h2>Vendor feedback</h2><p>Dated assessments of quality, timeliness, safety and communication.</p></div><v-btn v-if="editable('vendor_feedback')" color="primary" prepend-icon="mdi-plus" @click="open('vendor_feedback')">Add feedback</v-btn></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>VENDOR / WORK ORDER</th><th>DATE / REVIEWER</th><th>QUALITY</th><th>TIMELINESS</th><th>SAFETY</th><th>COMMUNICATION</th><th>COMMENTS</th></tr></thead><tbody><tr v-for="f in rows('vendor_feedback').slice().reverse()" :key="f.id"><td>{{f.vendor||'Restricted'}}<span class="cell-secondary">{{state.orders.find(o=>o.id===f.orderId)?.number||'General vendor feedback'}}</span></td><td>{{f.date||'Restricted'}}<span class="cell-secondary">{{who(f.createdBy)}}</span></td><td>{{f.quality??'—'}} / 5</td><td>{{f.timeliness??'—'}} / 5</td><td>{{f.safety??'—'}} / 5</td><td>{{f.communication??'—'}} / 5</td><td class="scope-cell">{{f.comments||'Restricted'}}<div v-for="(v,k) in f.data" :key="k" class="cell-secondary">{{k}}: {{v}}</div></td></tr><tr v-if="!rows('vendor_feedback').length"><td colspan="7" class="empty-state">No feedback recorded yet.</td></tr></tbody></table></div></section></template>
<template v-else><section class="panel"><div class="panel-top"><div><h2>Vendor & supplier reporting</h2><p>Approved commitments, settlements, quotation outcomes and vendor performance.</p></div><v-btn variant="outlined" prepend-icon="mdi-download" @click="exportReport">Export CSV</v-btn></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>VENDOR / STATUS</th><th>QUOTATIONS / SELECTED</th><th>WORK ORDERS</th><th>WO COMMITMENTS</th><th>APPROVED PURCHASES</th><th>NET PAID / TDS</th><th>OUTSTANDING</th><th>FEEDBACK</th></tr></thead><tbody><tr v-for="(r,i) in report" :key="r.vendorId||i"><td>{{r.name||'Restricted'}}<span class="cell-secondary">{{r.status}} · {{r.trade||''}}</span></td><td>{{r.quotations??'—'}} / {{r.selected??'—'}}</td><td>{{r.orders??'—'}}</td><td>{{money(r.workOrderValue)}}</td><td>{{money(r.purchaseValue)}}</td><td>{{money(r.paid)}}<span class="cell-secondary">TDS {{money(r.tds)}}</span></td><td>{{money(r.outstanding)}}</td><td>{{r.rating==null?'Not recorded':Number(r.rating).toFixed(1)+' / 5'}}<span class="cell-secondary">{{r.feedbackCount??'—'}} assessments</span></td></tr><tr v-if="!report.length"><td colspan="8" class="empty-state">No vendor reporting data available.</td></tr></tbody></table></div></section><section class="panel mt-6"><div class="panel-top"><h2>Purchase purpose trail</h2></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>PURCHASE ORDER</th><th>WORK ORDER / QUOTATION</th><th>WHY THIS PURCHASE</th><th>MATERIAL / PURPOSE</th></tr></thead><tbody><tr v-for="p in state.purchaseOrders.filter(p=>p.tenantId===tenantId)" :key="p.id"><td>{{p.number}}</td><td>{{p.orderNumber||'Legacy · link not recorded'}}<span class="cell-secondary">{{state.orders.find(o=>o.id===p.orderId)?.quotationNumber||'Legacy · quotation not recorded'}}</span></td><td class="scope-cell">{{p.purpose||'Legacy · purpose not recorded'}}</td><td class="scope-cell"><div v-for="l in p.lines" :key="l.id">{{l.material}} · {{l.purpose||'Legacy · purpose not recorded'}}</div></td></tr></tbody></table></div></section></template>
<v-alert v-if="failure" type="error" class="mt-5">{{failure}}</v-alert>
<v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" max-width="820"><v-card><v-card-title class="dialog-title">{{dialog==='rfq'?'Quotation work package':dialog==='quotation'?'Vendor quotation':dialog==='award'?'Select quotation':'Vendor feedback'}}<v-btn icon="mdi-close" variant="text" aria-label="Close form" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="error||failure" type="error" class="mb-4">{{error||failure}}</v-alert><v-form ref="formRef" @submit.prevent="save"><template v-if="dialog==='rfq'"><v-text-field v-model="form.title" label="Work package name *" :rules="[req]"/><v-textarea v-model="form.description" label="Scope to compare *" rows="2" :rules="[req]"/><v-select v-model="form.contractType" :items="contractTypes" label="Contract type *"/><v-select v-model="form.referenceOrderId" :items="state.orders.filter(o=>o.tenantId===tenantId).map(o=>({title:o.number+' · '+o.description,value:o.id}))" label="Reference existing work order (optional)" clearable/></template><template v-if="dialog==='quotation'"><v-select v-model="form.vendorId" :items="vendors.map(v=>({title:v.name,value:v.id}))" label="Vendor *" :rules="[req]"/><div class="form-two-columns"><v-text-field v-model="form.number" label="Quotation number *" :rules="[req]"/><v-text-field v-model="form.quotationDate" label="Quotation date *" type="date" :rules="[req]"/></div><v-textarea v-model="form.description" label="Quoted scope *" rows="2" :rules="[req]"/><div class="form-two-columns"><v-text-field v-model="form.price" label="Value including tax (₹) *" inputmode="decimal" :rules="[req,pos]"/><v-text-field v-model="form.deliveryDays" label="Delivery / execution days *" type="number" :rules="[pos]"/><v-text-field v-model="form.creditDays" label="Credit given (days) *" type="number" min="0" max="3650" :rules="[req,v=>Number.isInteger(Number(v))&amp;&amp;Number(v)>=0||'Use whole days ≥ 0']"/></div><v-textarea v-model="form.terms" label="Terms, exclusions and payment schedule *" rows="3" :rules="[req]"/></template><template v-if="dialog==='award'"><p class="dialog-context">{{quote(form.quotationId)?.vendor}} · {{quote(form.quotationId)?.number}} · {{money(quote(form.quotationId)?.amount)}}</p><v-textarea v-model="form.reason" label="Why choose this quotation? *" :rules="[req]" rows="3"/></template><template v-if="dialog==='vendor_feedback'"><v-select v-model="form.vendorId" :items="vendors.map(v=>({title:v.name,value:v.id}))" label="Vendor *" :rules="[req]" @update:model-value="form.orderId=''"/><v-select v-model="form.orderId" :items="state.orders.filter(o=>o.tenantId===tenantId&&o.vendorId===form.vendorId).map(o=>({title:o.number,value:o.id}))" label="Work order (optional)" clearable/><v-text-field v-model="form.date" type="date" label="Assessment date *" :rules="[req]"/><div class="form-two-columns"><v-select v-for="k in ['quality','timeliness','safety','communication']" :key="k" v-model="form[k]" :items="[1,2,3,4,5]" :label="k+' (1–5) *'"/></div><v-textarea v-model="form.comments" label="Feedback and recommended action *" :rules="[req]" rows="3"/></template><MetaFields v-if="dialog" :state="state" :user="user" :tenant-id="tenantId" :form-id="formForKind(dialog)" :record="form"/></v-form></v-card-text><v-card-actions class="dialog-actions"><v-btn @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn color="primary" :loading="busy" @click="save">{{dialog==='award'?'Save selection draft':'Save record'}}</v-btn></v-card-actions></v-card></v-dialog>
</template>
